function OverseaManageCatBallStarGroup:__init()
    self.stars = {}

end

function OverseaManageCatBallStarGroup:__delete()

end

function OverseaManageCatBallStarGroup:Awake()

end

function OverseaManageCatBallStarGroup:OnDestroy()

    self.controller = nil--luabehaviour 中CSharp
    self:Delete()
    self = nil
