--region logic

function OverseaManageCatBallStarGroup:FreshUI(star)
    local parent = self.controller.transform
    local count  = parent.childCount

    local isSuperStar = star > count
    local superStar   = star % count
    for i = 1, count do
        local starUISwi = self.stars[i]
        if isNull(starUISwi) then
            local starTrans = parent:GetChild(i - 1)
            starUISwi = starTrans.gameObject:GetComponent(UISwitchImageType)
            self.stars[i] = starUISwi
        end

        local status
        if isSuperStar then
            status = (superStar >= i or superStar == 0) and 3 or 2
        else
            status = (star > 0 and (superStar >= i or superStar == 0)) and 2 or 1
        end
        starUISwi.Status = status
    end
end

